newcode='''from collections import defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = defaultdict(list)
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            counts[color].append((r, c))
    background = max(counts, key=lambda color: len(counts[color]))
    out = [row[:] for row in grid]
    for color, points in counts.items():
        if color == background:
            continue
        for diagonal in (0, 1):
            groups = defaultdict(list)
            for r, c in points:
                key = r-c if diagonal == 0 else r+c
                groups[key].append((r, c))
            for key, members in groups.items():
                if len(members) < 2:
                    continue
                # Along either diagonal, row is a convenient coordinate.
                members.sort()
                for endpoint, step in ((members[0], -1), (members[-1], 1)):
                    r, c = endpoint
                    while True:
                        r += step
                        c += step if diagonal == 0 else -step
                        if not (0 <= r < h and 0 <= c < w):
                            break
                        if out[r][c] != background:
                            break
                        out[r][c] = color
    return out
'''
